#!/usr/bin/env python3
# =============================================================================
# gen_console_gz.py - pre-compresses the embedded web pages (StackChan-Companion)
# =============================================================================
# Reads the raw string literals of src/app/WebConsole.h (the SOURCE OF TRUTH,
# still editable as plain HTML/CSS/JS) and emits src/app/WebConsoleGz.h, which
# holds the SAME bytes gzipped as C arrays. WebApi serves those arrays with
# `Content-Encoding: gzip`.
#
# Why a build step rather than a checked-in blob regenerated by hand: the two
# files would drift the day someone edits the markup and forgets the script.
# PlatformIO runs this as a `pre:` extra_script of env:companion, so the header
# is regenerated before every compile - there is nothing to forget.
#
# Standalone use (verification, or a plain `python` run outside PlatformIO):
#     python scripts/build/gen_console_gz.py            # regenerate
#     python scripts/build/gen_console_gz.py --check    # verify round-trip, no write
#
# The output is BYTE-STABLE for a given input (gzip mtime pinned to 0, no
# filename in the header) and the file is only rewritten when its content
# changes: an unchanged console does not trigger a rebuild of WebApi.cpp.
# =============================================================================

import gzip
import hashlib
import io
import os
import re
import sys

# SCons `exec`s this file, so `__file__` does NOT exist under PlatformIO: the
# project root comes from the SCons environment there, and from this file's own
# location on a plain `python` run. Resolved once, at import.
if "__file__" in globals():
    # Three levels up from `scripts/build/`; asserted, see gates/check-a222.py.
    ROOT = os.path.dirname(os.path.dirname(os.path.dirname(
        os.path.abspath(__file__))))
    assert os.path.isfile(os.path.join(ROOT, "platformio.ini")), \
        "repo root not found from " + __file__
else:
    ROOT = os.getcwd()

SRC = os.path.join(ROOT, "src", "app", "WebConsole.h")
DST = os.path.join(ROOT, "src", "app", "WebConsoleGz.h")

# The literals to compress, in the order they appear in the generated header.
LITERALS = ("CONSOLE_HTML", "SWAGGER_HTML", "OPENAPI_JSON")


def extract(source: str, name: str) -> bytes:
    """Returns the payload of `inline const char NAME[] PROGMEM = R"TAG(...)TAG";`.

    A raw string literal has no escapes, so a non-greedy match up to the exact
    closing delimiter is exact - the delimiter cannot appear inside by
    definition of a raw literal (the compiler would have ended it there too).
    """
    m = re.search(
        r'inline\s+const\s+char\s+' + re.escape(name) +
        r'\s*\[\]\s*PROGMEM\s*=\s*R"([A-Za-z0-9_]*)\(',
        source)
    if not m:
        raise SystemExit("gen_console_gz: literal %s not found in %s" % (name, SRC))
    tag = m.group(1)
    start = m.end()
    end = source.index(')' + tag + '"', start)
    return source[start:end].encode("utf-8")


def compress(payload: bytes) -> bytes:
    """gzip, level 9, deterministic (mtime=0, no name) so the output is stable."""
    buf = io.BytesIO()
    # GzipFile rather than gzip.compress(): the latter stamps the current time
    # in the header, which would make every build produce a different array and
    # rebuild the world for nothing.
    with gzip.GzipFile(fileobj=buf, mode="wb", compresslevel=9, mtime=0) as gz:
        gz.write(payload)
    return buf.getvalue()


def c_array(name: str, blob: bytes) -> str:
    rows = []
    for i in range(0, len(blob), 16):
        rows.append("    " + ",".join("0x%02x" % b for b in blob[i:i + 16]) + ",")
    return ("inline constexpr size_t %s_GZ_LEN = %d;\n"
            "inline const uint8_t %s_GZ[] PROGMEM = {\n%s\n};\n"
            % (name, len(blob), name, "\n".join(rows)))


def build() -> str:
    with open(SRC, "r", encoding="utf-8") as f:
        source = f.read()
    digest = hashlib.sha256(source.encode("utf-8")).hexdigest()[:16]

    body, summary = [], []
    for name in LITERALS:
        raw = extract(source, name)
        blob = compress(raw)
        # Self-check at GENERATION time: what we ship must inflate back to the
        # exact bytes we read. A silently corrupt array would only show up as a
        # blank page on a robot that is hard to debug over -77 dBm of WiFi.
        if gzip.decompress(blob) != raw:
            raise SystemExit("gen_console_gz: round-trip failed for %s" % name)
        body.append(c_array(name, blob))
        summary.append("//   %-13s %7d B -> %6d B gz (%.1fx)"
                       % (name, len(raw), len(blob), len(raw) / float(len(blob))))

    return ("""#pragma once
// =============================================================================
// WebConsoleGz.h - GENERATED FILE, DO NOT EDIT
// =============================================================================
// (CONSOLE_SRC_SHA below is published by GET /api/firmware: it lets a running
//  robot be compared to a working copy with no ELF and no flash dump -
//  `python scripts/build/gen_console_gz.py --check` prints the same digest.)
// gzip of the literals of WebConsole.h (the source of truth: edit the markup
// THERE). Regenerated by scripts/build/gen_console_gz.py, run as a `pre:` action of
// env:companion - see platformio.ini.
//
// Served by WebApi with `Content-Encoding: gzip`: the browser inflates. The
// compressed bytes REPLACE the plain ones in flash (WebApi no longer names the
// plain literals; -fdata-sections/--gc-sections drops them), so the page loads
// several times faster AND the firmware shrinks.
//
%s
//
// source sha256[0:16] = %s
// =============================================================================

#include <stddef.h>
#include <stdint.h>
#include <pgmspace.h>

namespace sce {

inline constexpr char CONSOLE_SRC_SHA[] = "%s";

%s
} // namespace sce
""" % ("\n".join(summary), digest, digest, "\n".join(body)), summary)


def main(argv):
    text, summary = build()
    check_only = "--check" in argv
    old = None
    if os.path.exists(DST):
        with open(DST, "r", encoding="utf-8") as f:
            old = f.read()
    if check_only:
        print("\n".join(s[3:] for s in summary))
        if old != text:
            print("gen_console_gz: WebConsoleGz.h is STALE")
            return 1
        print("gen_console_gz: WebConsoleGz.h is up to date")
        return 0
    if old != text:
        with open(DST, "w", encoding="utf-8", newline="\n") as f:
            f.write(text)
        print("gen_console_gz: regenerated src/app/WebConsoleGz.h")
    else:
        print("gen_console_gz: src/app/WebConsoleGz.h up to date")
    print("\n".join(s[3:] for s in summary))
    return 0


# PlatformIO (SCons) `exec`s this file; a bare `python` run just calls main().
try:
    Import("env")  # noqa: F821  - injected by SCons
    ROOT = env.subst("$PROJECT_DIR")  # noqa: F821
    SRC = os.path.join(ROOT, "src", "app", "WebConsole.h")
    DST = os.path.join(ROOT, "src", "app", "WebConsoleGz.h")
    if main([]) != 0:
        raise SystemExit("gen_console_gz: generation failed")
except NameError:
    if __name__ == "__main__":
        sys.exit(main(sys.argv[1:]))
